{
  "groups": [
    {
      "group_id": "low_rate_fixed_vulnerable",
      "rule": "rate_type == 'fixed' and origination_year <= 2021 and mortgage_rate_pct < 3.0",
      "rationale": "Borrowers who secured historically low rates face extreme payment shock at renewal and are highly motivated to negotiate or seek retention offers."
    },
    {
      "group_id": "high_debt_young_family",
      "rule": "n_children >= 2 and household_income_cad < 100000 and mortgage_balance_cad > 400000",
      "rationale": "Large households with limited income and high mortgage debt have minimal financial buffer to absorb payment increases."
    },
    {
      "group_id": "prime_uninsured_equity_rich",
      "rule": "insured_flag == False and credit_score_band == '720_plus' and mortgage_balance_cad < 400000",
      "rationale": "High-credit, low-leverage uninsured borrowers have significant equity and strong market mobility, making them prime targets for competitive switching."
    },
    {
      "group_id": "variable_rate_stretched",
      "rule": "rate_type == 'variable' and payment_structure == 'adjustable_payment' and credit_utilization_pct > 40",
      "rationale": "These borrowers are experiencing immediate cash flow pressure from rate hikes combined with high revolving debt levels."
    },
    {
      "group_id": "credit_constrained_insured",
      "rule": "insured_flag == True and credit_score_band in ['below_600', '600_659']",
      "rationale": "Borrowers with lower credit scores have restricted lender options and are functionally captive, limiting their ability to switch."
    },
    {
      "group_id": "near_retirement_stable",
      "rule": "primary_borrower_age >= 55 and has_savings == True and has_investments == True",
      "rationale": "Older borrowers with accumulated assets are generally more risk-averse and prioritize stability over aggressive rate shopping."
    },
    {
      "group_id": "recent_homebuyer_high_rate",
      "rule": "origination_year >= 2022 and mortgage_rate_pct > 5.0",
      "rationale": "Borrowers who entered the market at the peak of recent rates are already acclimated to high costs but may be struggling with property value decline."
    },
    {
      "group_id": "life_event_impacted",
      "rule": "life_event_6m == True and life_event_type != 'none'",
      "rationale": "Major life transitions create a need for liquidity and flexibility that often triggers a search for alternative mortgage solutions."
    }
  ]
}
